package hello.hellospring.domain;

import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;

// 11강 회원 도메인
// 요구사항의 데이터는 회원ID, 이름 두 개뿐
//
// 24강 JPA 엔티티 매핑
// @Entity 가 붙으면 JPA 가 관리하는 엔티티가 됨
// 스프링 부트 3.x 라서 javax.persistence 가 아니라 jakarta.persistence 를 import 함
@Entity
public class Member {

    // id 는 고객이 정하는 값이 아니라 시스템이 저장할 때 정해주는 값
    // @Id 는 PK
    // IDENTITY 는 DB 가 id 를 알아서 만들어주는 방식. ddl 의 generated by default as identity 와 맞춘 것
    @Id @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    // 컬럼 이름도 name 이라 따로 매핑 안 해도 됨
    private String name;

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }
}
